CREATE TABLE creative_assets(id uuid PRIMARY KEY,owner_name text NOT NULL,object_key text NOT NULL,sha256 char(64) NOT NULL,byte_size int NOT NULL CHECK(byte_size BETWEEN 1 AND 5242880),width int NOT NULL CHECK(width BETWEEN 1 AND 4096),height int NOT NULL CHECK(height BETWEEN 1 AND 4096),created timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE creatives(id uuid PRIMARY KEY,campaign_id uuid NOT NULL REFERENCES campaigns(id),version int NOT NULL CHECK(version>0),format text NOT NULL CHECK(format IN ('TEXT','IMAGE')),headline text NOT NULL CHECK(length(headline) BETWEEN 1 AND 160),description text NOT NULL CHECK(length(description)<=500),destination text NOT NULL,asset_id uuid REFERENCES creative_assets(id),status text NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED')),created timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(campaign_id,version),CHECK((format='TEXT' AND asset_id IS NULL) OR (format='IMAGE' AND asset_id IS NOT NULL)));
ALTER TABLE campaigns ADD COLUMN current_creative_id uuid REFERENCES creatives(id);
INSERT INTO creatives(id,campaign_id,version,format,headline,description,destination,status) SELECT gen_random_uuid(),id,1,'TEXT',headline,'',destination,CASE WHEN approved THEN 'APPROVED' ELSE 'PENDING' END FROM campaigns;
UPDATE campaigns c SET current_creative_id=cr.id FROM creatives cr WHERE cr.campaign_id=c.id AND cr.version=1;
CREATE FUNCTION initialize_campaign_creative() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE creative uuid:=gen_random_uuid(); BEGIN INSERT INTO creatives(id,campaign_id,version,format,headline,description,destination,status) VALUES(creative,NEW.id,1,'TEXT',NEW.headline,'',NEW.destination,CASE WHEN NEW.approved THEN 'APPROVED' ELSE 'PENDING' END); UPDATE campaigns SET current_creative_id=creative WHERE id=NEW.id; RETURN NEW; END $$;
CREATE TRIGGER campaign_initial_creative AFTER INSERT ON campaigns FOR EACH ROW EXECUTE FUNCTION initialize_campaign_creative();
CREATE TABLE creative_reviews(id bigserial PRIMARY KEY,creative_id uuid NOT NULL REFERENCES creatives(id),actor text NOT NULL,action text NOT NULL,reason text NOT NULL,created timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TRIGGER creative_review_immutable BEFORE UPDATE OR DELETE ON creative_reviews FOR EACH ROW EXECUTE FUNCTION append_only_financial_history();
CREATE FUNCTION protect_creative_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (NEW.id,NEW.campaign_id,NEW.version,NEW.format,NEW.headline,NEW.description,NEW.destination,NEW.asset_id,NEW.created) IS DISTINCT FROM (OLD.id,OLD.campaign_id,OLD.version,OLD.format,OLD.headline,OLD.description,OLD.destination,OLD.asset_id,OLD.created) THEN RAISE EXCEPTION 'Create a new creative version instead of editing reviewed content'; END IF; RETURN NEW; END $$;
CREATE TRIGGER creative_version_immutable BEFORE UPDATE ON creatives FOR EACH ROW EXECUTE FUNCTION protect_creative_version();
ALTER TABLE decisions ADD COLUMN creative_id uuid REFERENCES creatives(id);
ALTER TABLE decisions ADD COLUMN creative_headline text;
ALTER TABLE decisions ADD COLUMN creative_description text;
ALTER TABLE decisions ADD COLUMN creative_destination text;
UPDATE decisions d SET creative_id=cr.id,creative_headline=cr.headline,creative_description=cr.description,creative_destination=cr.destination FROM campaigns c JOIN creatives cr ON cr.id=c.current_creative_id WHERE c.id=d.campaign_id;
CREATE INDEX creative_campaign ON creatives(campaign_id,version DESC);
CREATE INDEX creative_approved_asset ON creatives(asset_id,status);
CREATE INDEX creative_asset_owner ON creative_assets(owner_name,created DESC);
